 private int drawerW(){return Math.min(400,w-32);}private int drawerH(){return Math.min(300,h-24);}private int drawerX(){return left+(w-drawerW())/2;}private int drawerY(){return top+(h-drawerH())/2;}
 private List<ModLibraryService.Installed> filtered(){String folder=AddonRules.folder(kind);return installed.stream().filter(item->item.folder().equals(folder)&&(item.name()+" "+item.id()+" "+item.filename()).toLowerCase(Locale.ROOT).contains(query.strip().toLowerCase(Locale.ROOT))).toList();}
 private List<?> current(){return tab.equals("installed")?filtered():tab.equals("pending")?pending.asList():projects;}
 private boolean isQueued(String folder,String filename){for(var raw:pending){var a=raw.getAsJsonObject();if(a.get("folder").getAsString().equals(folder)&&a.get("filename").getAsString().equals(filename))return true;}return false;}
 private void navigate(int delta){if(busy)return;int limit=rows*2,count=discovery()?total:current().size();int next=Math.clamp(page+delta,0,Math.max(0,(count-1)/limit));if(next!=page){page=next;selected=null;if(discovery())discover();else rebuildWidgets();}}
 private void refresh(){busy=true;status="Lese lokale Metadaten …";int epoch=++request;var mc=minecraft;ModLibraryService.async(()->new Object[]{ModLibraryService.installed(root),ModLibraryService.readQueue(root)}).whenComplete((result,error)->mc.execute(()->{if(mc.gui.screen()!=this||epoch!=request)return;busy=false;if(error!=null)status=message(error);else{installed=(List<ModLibraryService.Installed>)result[0];pending=(JsonArray)result[1];status=pending.isEmpty()?"Änderungen gelten nach einem vollständigen Spielneustart":pending.size()+" Änderungen für nächsten Start vorgemerkt";}rebuildWidgets();}));}
 private void discover(){busy=true;status="Suche passende Minecraft-26.2-Erweiterungen …";int epoch=++request;String term=query,type=kind,source=provider;int offset=page*rows*2;int limit=rows*2;searchPageSize=limit;var mc=minecraft;rebuildWidgets();ModLibraryService.async(()->ModLibraryService.search(source,term,type,offset,limit)).whenComplete((result,error)->mc.execute(()->{if(mc.gui.screen()!=this||epoch!=request)return;busy=false;if(error!=null){status=message(error);projects=List.of();total=0;completedSearch=null;}else{projects=result.projects();total=result.total();completedSearch=new SearchStamp(source,term,type,offset,limit);status=total+" kompatible Ergebnisse · "+(source.equals("curseforge")?"CurseForge":"Modrinth");loadIcons();}rebuildWidgets();}));}
 private void loadIcons(){for(var project:projects)if(!project.iconUrl().isEmpty()&&!icons.containsKey(project.provider()+":"+project.id())&&requestedIcons.size()<32&&requestedIcons.add(project.provider()+":"+project.id())){var mc=minecraft;ModLibraryService.iconAsync(project.iconUrl()).whenComplete((bytes,error)->mc.execute(()->{requestedIcons.remove(project.provider()+":"+project.id());if(mc.gui.screen()==this&&bytes!=null)registerIcon(project.provider()+":"+project.id(),bytes);}));}}
 private void registerIcon(String key,byte[] bytes){if(icons.containsKey(key)||!AddonRules.png(bytes))return;try{NativeImage image=NativeImage.read(bytes);if(image.getWidth()>128||image.getHeight()>128){float ratio=128f/Math.max(image.getWidth(),image.getHeight());var thumbnail=new NativeImage(Math.max(1,Math.round(image.getWidth()*ratio)),Math.max(1,Math.round(image.getHeight()*ratio)),false);try{image.resizeSubRectTo(0,0,image.getWidth(),image.getHeight(),thumbnail);}catch(Throwable failure){thumbnail.close();throw failure;}finally{image.close();}image=thumbnail;}Identifier id=Identifier.fromNamespaceAndPath("votex_client","library/"+UUID.randomUUID());int width=image.getWidth(),height=image.getHeight();if(icons.size()>=80){var eldest=icons.entrySet().iterator().next();minecraft.getTextureManager().release(eldest.getValue().texture());icons.remove(eldest.getKey());}minecraft.getTextureManager().register(id,new DynamicTexture(()->"Votex mod icon",image));icons.put(key,new Icon(id,width,height));}catch(Exception ignored){}}
 private void work(Callable<String> job){work(null,job);}
 private void work(String title,Callable<String> job){if(busy)return;long install=title==null?0:InstallationFeedback.ACTIVITY.begin(title,System.nanoTime());busy=true;status="Prüfe Abhängigkeiten und Dateien …";int epoch=++request;var mc=minecraft;rebuildWidgets();ModLibraryService.async(()->ModLibraryService.withProgress(update->{if(install!=0)InstallationFeedback.ACTIVITY.progress(install,update.detail(),update.completed(),update.total());},()->new Object[]{job.call(),ModLibraryService.readQueue(root)})).whenComplete((result,error)->mc.execute(()->{if(install!=0)InstallationFeedback.ACTIVITY.finish(install,error==null,error==null?(String)result[0]:message(error),System.nanoTime());if(mc.gui.screen()!=this||epoch!=request)return;busy=false;if(error!=null)status=message(error);else{status=(String)result[0];pending=(JsonArray)result[1];if(selected instanceof JsonObject previous)selected=pending.asList().stream().map(JsonElement::getAsJsonObject).filter(action->action.get("folder").equals(previous.get("folder"))&&action.get("filename").equals(previous.get("filename"))).findFirst().orElse(null);}rebuildWidgets();}));}
 private static String message(Throwable error){while(error.getCause()!=null)error=error.getCause();if(error instanceof java.util.zip.ZipException)return "Diese ZIP-Datei ist beschädigt oder unvollständig.";return error.getMessage()==null?error.getClass().getSimpleName():error.getMessage();}
