 private void importPaths(List<Path> paths){String type=kind;List<Path> files=paths.stream().limit(16).toList();work("Lokale Dateien importieren",()->{int count=0;for(var file:files)count+=ModLibraryService.importFile(root,file,type);return count+(count==1?" Datei":" Dateien")+" für nächsten Start vorgemerkt";});}
