 private double localX(double x){return displayedMotion.localX(x/scale);}private double localY(double y){return displayedMotion.localY(y/scale);}
 private MouseButtonEvent local(MouseButtonEvent event){return new MouseButtonEvent(localX(event.x()),localY(event.y()),event.buttonInfo());}
 @Override public boolean mouseClicked(MouseButtonEvent event,boolean twice){var logical=local(event);if(compact&&selected!=null){if(logical.x()<drawerX()||logical.x()>drawerX()+drawerW()||logical.y()<drawerY()||logical.y()>drawerY()+drawerH()){selected=null;rebuildWidgets();return true;}return super.mouseClicked(logical,twice);}if(super.mouseClicked(logical,twice))return true;if(setupOnly()||logical.x()<left+16||logical.x()>left+cw||logical.y()<top+listY||logical.y()>=top+listY+rows*72)return false;int col=(int)((logical.x()-left-16)/(cardW+10)),row=(int)((logical.y()-top-listY)/72);if(col>1||logical.x()>=left+16+col*(cardW+10)+cardW||logical.y()>=top+listY+row*72+64)return false;List<?> items=current();int index=(discovery()?0:page*rows*2)+row*2+col;if(index>=0&&index<items.size()){Object raw=items.get(index);selected=raw instanceof JsonElement json?json.getAsJsonObject():raw;rebuildWidgets();return true;}return false;}
 @Override public void tick(){super.tick();if(discovery()&&!busy&&searchPageSize!=rows*2)discover();}
 @Override public boolean mouseReleased(MouseButtonEvent e){return super.mouseReleased(local(e));}
 @Override public boolean mouseDragged(MouseButtonEvent e,double dx,double dy){return super.mouseDragged(local(e),dx/(scale*displayedMotion.scale()),dy/(scale*displayedMotion.scale()));}
 @Override public void mouseMoved(double x,double y){super.mouseMoved(localX(x),localY(y));}
 @Override public boolean mouseScrolled(double x,double y,double dx,double dy){if(dy==0||compact&&selected!=null)return false;navigate(-(int)Math.signum(dy));return true;}
 @Override public boolean keyPressed(KeyEvent e){if(compact&&selected!=null&&e.key()==GLFW.GLFW_KEY_ESCAPE){selected=null;rebuildWidgets();return true;}if((e.key()==GLFW.GLFW_KEY_ENTER||e.key()==GLFW.GLFW_KEY_KP_ENTER)&&search!=null&&search.isFocused()){page=0;if(discovery())discover();else rebuildWidgets();return true;}return super.keyPressed(e);}
 @Override public void removed(){for(var icon:icons.values())minecraft.getTextureManager().release(icon.texture());icons.clear();requestedIcons.clear();cardMotion.clear();request++;}
